declare(strict_types=1);require dirname(__DIR__).'/config.php';admin_required();require dirname(__DIR__).'/lib/traffic.php';
$error='';try{$days=max(1,min(90,(int)($_GET['days']??31)));$s=traffic_stats($days);$today=traffic_stats(1);$pct=TRAFFIC_LIMIT_BYTES>0?$today['bytes']/TRAFFIC_LIMIT_BYTES*100:0;$recent=traffic_recent(100);}catch(Throwable $e){$error=$e->getMessage();$days=31;$s=$today=['pv'=>0,'uv'=>0,'bytes'=>0,'devices'=>[],'browsers'=>[],'pages'=>[]];$pct=0;$recent=[];}
