?><!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>방문·트래픽 통계</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f6f9;color:#172033;font-family:system-ui,-apple-system,"Noto Sans KR",sans-serif}.w{max-width:1180px;margin:auto;padding:20px}.top,.card{background:#fff;border:1px solid #dde3ec;border-radius:15px;padding:18px;margin-bottom:14px}.top{display:flex;justify-content:space-between;gap:12px;align-items:center}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.k{background:#fff;border:1px solid #dde3ec;border-radius:14px;padding:16px}.k b{display:block;font-size:25px;margin-top:6px}.muted{color:#667085;font-size:13px}.bar{height:18px;background:#e9edf3;border-radius:99px;overflow:hidden}.bar i{display:block;height:100%;background:#1f5eff}.warn{color:#b42318;font-weight:800}.err{background:#fff0f0;color:#b42318;padding:12px;border-radius:10px}table{width:100%;border-collapse:collapse;font-size:13px}th,td{padding:9px;border-bottom:1px solid #e6e9ee;text-align:left}th{background:#f7f8fa;position:sticky;top:0}.scroll{max-height:520px;overflow:auto}.cols{display:grid;grid-template-columns:1fr 1fr;gap:14px}a{color:#174ea6}@media(max-width:800px){.grid{grid-template-columns:1fr 1fr}.cols{grid-template-columns:1fr}.top{display:block}}</style></head><body><main class="w"><section class="top"><div><h1 style="margin:0">방문자 · 트래픽 통계</h1><div class="muted">MySQL 저장 · 브라우저 Resource Timing 기반 전송량 관측</div></div><div><a href="index.php">← 사진관리</a> · <a href="../index.php">사이트 보기</a></div></section><?php if($error):?><div class="err">DB 조회 실패: <?=h($error)?> · install_traffic.php 실행 여부를 확인하세요.</div><?php endif?><section class="grid"><div class="k"><span class="muted">오늘 방문(PV)</span><b><?=number_format($today['pv'])?></b></div><div class="k"><span class="muted">오늘 고유 IP</span><b><?=number_format($today['uv'])?></b></div><div class="k"><span class="muted">오늘 관측 전송량</span><b><?=fmtb((int)$today['bytes'])?></b></div><div class="k"><span class="muted">1.6GB 대비</span><b class="<?=$pct>=80?'warn':''?>"><?=number_format($pct,1)?>%</b></div></section><section class="card"><h2>오늘 트래픽 사용률</h2><div class="bar"><i style="width:<?=min(100,$pct)?>%"></i></div><p><b><?=fmtb((int)$today['bytes'])?></b> / <?=fmtb(TRAFFIC_LIMIT_BYTES)?> · 80% 경고 <?=fmtb((int)(TRAFFIC_LIMIT_BYTES*.8))?></p><p class="muted">Cafe24 계정 전체 실제 트래픽과는 차이가 날 수 있는 웹앱 자체 관측값입니다.</p></section><div class="cols"><section class="card"><h2>최근 <?=$days?>일 요약</h2><p>PV <b><?=number_format($s['pv'])?></b> · 고유 IP <b><?=number_format($s['uv'])?></b> · 관측 전송량 <b><?=fmtb((int)$s['bytes'])?></b></p><h3>디바이스</h3><?php foreach($s['devices'] as$k=>$v):?><div><?=h($k)?> <b><?=$v?></b></div><?php endforeach?><h3>브라우저</h3><?php foreach($s['browsers'] as$k=>$v):?><div><?=h($k)?> <b><?=$v?></b></div><?php endforeach?></section><section class="card"><h2>페이지별 PV</h2><?php foreach($s['pages'] as$k=>$v):?><div><?=h($k)?> <b><?=$v?></b></div><?php endforeach?><h3>기간</h3><a href="?days=7">7일</a> · <a href="?days=31">31일</a> · <a href="?days=90">90일</a></section></div><section class="card"><h2>최근 접속 100건</h2><div class="scroll"><table><thead><tr><th>일시</th><th>IP</th><th>디바이스</th><th>OS</th><th>브라우저</th><th>페이지</th><th>유입</th></tr></thead><tbody><?php foreach($recent as$r):?><tr><td><?=h((string)($r['ts']??''))?></td><td><?=h((string)($r['ip']??''))?></td><td><?=h((string)($r['device']??''))?></td><td><?=h((string)($r['os']??''))?></td><td><?=h((string)($r['browser']??''))?></td><td><?=h((string)($r['page']??''))?></td><td><?=h(mb_strimwidth((string)($r['referer']??''),0,50,'…'))?></td></tr><?php endforeach?></tbody></table></div></section></main></body></html>
